    [TYPES.BUG]: { [TYPES.FIRE]: 0.5, [TYPES.GRASS]: 2.0, [TYPES.POISON]: 0.5, [TYPES.FLYING]: 0.5, [TYPES.FIGHTING]: 0.5, [TYPES.GHOST]: 0.5, [TYPES.STEEL]: 0.5, [TYPES.FAIRY]: 0.5, [TYPES.PSYCHIC]: 2.0, [TYPES.DARK]: 2.0 },
    [TYPES.POISON]: { [TYPES.GRASS]: 2.0, [TYPES.POISON]: 0.5, [TYPES.GROUND]: 0.5, [TYPES.ROCK]: 0.5, [TYPES.GHOST]: 0.5, [TYPES.STEEL]: 0.0, [TYPES.FAIRY]: 2.0 },
