    [TYPES.GHOST]: { [TYPES.NORMAL]: 0.0, [TYPES.PSYCHIC]: 2.0, [TYPES.GHOST]: 2.0, [TYPES.DARK]: 0.5 },
    [TYPES.DRAGON]: { [TYPES.DRAGON]: 2.0, [TYPES.STEEL]: 0.5, [TYPES.FAIRY]: 0.0 },
